--
-- Name: archive_leads(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.archive_leads(p_lead_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  n integer;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;

  UPDATE public.leads
  SET archived_at = now(),
      archived_by = auth.uid(),
      updated_at = now()
  WHERE id = ANY (p_lead_ids)
    AND archived_at IS NULL
    AND public.can_manage_lead_archive(leads.tenant_id);

  GET DIAGNOSTICS n = ROW_COUNT;
  IF n = 0 AND EXISTS (
    SELECT 1 FROM public.leads l
    WHERE l.id = ANY (p_lead_ids)
      AND NOT public.can_manage_lead_archive(l.tenant_id)
  ) THEN
    RAISE EXCEPTION 'רק בעלים יכולים להעביר לידים לארכיון';
  END IF;
  RETURN n;
END;
$$;


ALTER FUNCTION public.archive_leads(p_lead_ids uuid[]) OWNER TO postgres;

--
-- Name: assign_role_by_email(text, public.app_role); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.assign_role_by_email(_email text, _role public.app_role) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  _user_id uuid;
BEGIN
  SELECT id INTO _user_id FROM auth.users WHERE email = _email;
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'User with email % not found', _email;
  END IF;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (_user_id, _role)
  ON CONFLICT (user_id, role) DO NOTHING;

  RETURN _user_id;
END;
$$;


