--
-- Name: can_manage_lead_archive(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_manage_lead_archive(_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT
    auth.uid() IS NOT NULL
    AND (
      public.is_super_admin(auth.uid())
      OR EXISTS (
        SELECT 1
        FROM public.user_roles ur
        WHERE ur.user_id = auth.uid()
          AND ur.tenant_id = _tenant_id
          AND ur.role = 'owner'::app_role
      )
      OR EXISTS (
        SELECT 1
        FROM public.tenant_users tu
        WHERE tu.user_id = auth.uid()
          AND tu.tenant_id = _tenant_id
          AND lower(tu.role) IN ('owner', 'admin')
      )
    );
$$;


ALTER FUNCTION public.can_manage_lead_archive(_tenant_id uuid) OWNER TO postgres;

--
-- Name: can_manage_user_permissions(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.can_manage_user_permissions(target_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM user_roles
    WHERE user_id = auth.uid() AND role = 'super_admin'
  )
  OR
  EXISTS (
    SELECT 1
    FROM user_roles ur
    JOIN tenant_users tu_manager ON tu_manager.user_id = ur.user_id
    JOIN tenant_users tu_target ON tu_target.tenant_id = tu_manager.tenant_id
    WHERE ur.user_id = auth.uid()
      AND ur.role = 'owner'
      AND tu_target.user_id = target_user_id
  )
  OR
  target_user_id = auth.uid();
$$;


ALTER FUNCTION public.can_manage_user_permissions(target_user_id uuid) OWNER TO postgres;

