CREATE FUNCTION public.claude_notify_david(p_message text, p_tenant uuid DEFAULT '2dcdaac6-41bf-42cc-86bf-9a0b4b2e6019'::uuid, p_chat_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
