    transcription text,
    transcription_status text,
    transcription_error text,
    summary_file_url text,
    audio_file_path text,
    audio_file_paths text[],
    summary_md text,
    summary_generated_at timestamp with time zone,
    folder_id uuid,
    thumbnail_path text,
    suggested_client_id uuid,
